import { TropMail } from "@tropmail/sdk";

const client = new TropMail({ apiKey: process.env.TROPMAIL_API_KEY! });
const mailboxId = "11111111-1111-1111-1111-111111111111";
const attachmentId = "660e8400-e29b-41d4-a716-446655440002";

await client.attachments.scan(mailboxId, attachmentId);
let info = await client.attachments.get(mailboxId, attachmentId);
while (info.scan_status === "Processing") {
  await new Promise((r) => setTimeout(r, 2000));
  info = await client.attachments.get(mailboxId, attachmentId);
}
console.log(info.scan_status);

